// Budget table: per-stage percentiles with headroom (plain JS)
function budgetCheck(stages, budgetP99) {
  const serial = stages.reduce((s, x) => s + x.p99, 0);
  return stages.map((st) => ({
    name: st.name,
    share: Math.round((st.p99 / serial) * 100) + "% of tail",
    over: st.p99 > st.allowance ? `OVER by ${st.p99 - st.allowance}ms` : "within",
  })).concat([{ totalSerialP99: serial, budget: budgetP99, fits: serial <= budgetP99 }]);
}
// Tail owner = biggest share: optimize there first, nowhere else.

